out = []
for it in items:
    slug = it["slug"]
    if slug not in new_desc:
        raise SystemExit(f"missing description for {slug}")
    it["description"] = new_desc[slug]
    if slug in crossrefs:
        cr = crossrefs[slug]
        if "associated_creature" in cr:
            it["associated_creature"] = cr["associated_creature"]
        if "related_creatures" in cr:
            it["related_creatures"] = cr["related_creatures"]
        if "featured_in_stories" in cr:
            it["featured_in_stories"] = cr["featured_in_stories"]
    out.append(it)

with open('batch-13-output.json', 'w', encoding='utf-8') as f:
    json.dump(out, f, ensure_ascii=False, indent=2)
    f.write("\n")

print(f"wrote {len(out)} items")
